// Generated by scripts/gen-lettering-charset.py from the bundled lettering fonts. Do not edit.
/** Code points every lettering face (body regular/bold and SFX) can draw. */
export const LETTERING_RANGES: readonly (readonly [number, number])[] = [[0xd, 0xd], [0x20, 0x7e], [0xa0, 0xac], [0xae, 0xff], [0x131, 0x131], [0x152, 0x153], [0x2c6, 0x2c6], [0x2da, 0x2da], [0x2dc, 0x2dc], [0x300, 0x301], [0x303, 0x304], [0x308, 0x308], [0x2013, 0x2014], [0x2018, 0x201a], [0x201c, 0x201e], [0x2022, 0x2022], [0x2026, 0x2026], [0x2039, 0x203a], [0x2044, 0x2044], [0x20ac, 0x20ac], [0x2122, 0x2122], [0x2212, 0x2212], [0x2215, 0x2215]];

export const LETTERING_SUPPORTED_SUMMARY = 'Lettering supports Western European (Latin-1) letters such as é, ñ, ü, ß, ø and Æ, plus Œ, œ, ı and common punctuation (– — ‘ ’ “ ” „ … • € ™). Other scripts and symbols, for example Ł, ő, Č, Greek, Cyrillic, Chinese, Japanese, Korean and emoji, are not supported yet.';

/** Distinct characters in `text` that the lettering fonts cannot draw, in order of first use. */
export function unsupportedLetteringChars(text: string): string[] {
  const seen: string[] = [];
  for (const ch of text) {
    if (/\s/.test(ch)) continue;
    const cp = ch.codePointAt(0)!;
    if (!LETTERING_RANGES.some(([a, b]) => cp >= a && cp <= b) && !seen.includes(ch)) seen.push(ch);
  }
  return seen;
}

/** The same actionable message the server returns. */
export function unsupportedLetteringMessage(chars: string[]): string {
  const shown = chars.slice(0, 12).join(", ") + (chars.length > 12 ? "…" : "");
  return `These characters can't be lettered yet: ${shown}. ${LETTERING_SUPPORTED_SUMMARY} Replace or remove them (for example Ł → L), then try again. Your text is never changed for you.`;
}
